:root {
  --paper: #f4ecd8;
  --paper-soft: #faf3df;
  --ink: #1f1b16;
  --ink-light: #4a3f33;
  --ink-muted: #5f5545;
  --cream: #f7f0dd;
  --cream-soft: #dbcfb6;
  --vermilion: #c1272d;
  --oxblood: #9f1c1f;
  --struck: #8a7e6c;
