}

body { margin: 0; background: #0f0c09; }
#root { position: relative; width: 100%; height: 100%; overflow: hidden; background: #0f0c09; color: var(--ink); font-family: var(--serif); }

/* Full-frame layers */
.layer { position: absolute; inset: 0; overflow: hidden; }
.fill { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.paper-bg { position: absolute; inset: 0; background: var(--paper) url("img/paper-texture.jpg") center / cover; }
.scrim-bottom { position: absolute; left: 0; right: 0; bottom: 0; height: 46%; background: linear-gradient(to top, rgba(12, 9, 6, 0.86), rgba(12, 9, 6, 0.45) 45%, rgba(12, 9, 6, 0)); }
.scrim-left { position: absolute; top: 0; bottom: 0; left: 0; width: 62%; background: linear-gradient(to right, rgba(12, 9, 6, 0.82), rgba(12, 9, 6, 0.4) 60%, rgba(12, 9, 6, 0)); }

/* Typewriter label */
.label { font-family: var(--type); font-size: 26px; letter-spacing: 0.14em; text-transform: uppercase; }

/* Strikeable phrase: the rule is a scaled block laid over the words */
.strikeable { position: relative; display: inline-block; }
.tk-strike { position: absolute; left: -0.06em; right: -0.06em; top: 52%; height: 0.075em; min-height: 4px; background: var(--vermilion); transform-origin: left center; transform: scaleX(0); border-radius: 2px; }
.caret { display: inline-block; width: 0.07em; min-width: 4px; height: 0.95em; margin-left: 0.06em; vertical-align: -0.1em; background: var(--vermilion); }

/* Captions: one track, bottom centre */
.captions { position: absolute; left: 0; right: 0; bottom: 64px; height: 120px; z-index: 50; pointer-events: none; }
.tk-cap { position: absolute; left: 50%; bottom: 0; width: 1500px; margin-left: -750px; text-align: center; font-family: var(--serif); font-size: 44px; line-height: 1.3; opacity: 0; }
.tk-cap--light { color: var(--cream); text-shadow: 0 2px 14px rgba(0, 0, 0, 0.85), 0 0 2px rgba(0, 0, 0, 0.9); }
.tk-cap--dark { color: var(--ink); }

