js='''tl.fromTo("#rule",{scaleX:0},{scaleX:1,duration:.5,ease:"power2.out"},.2);
TK.type(tl,document.querySelector("#type1"),.5,{cps:15});TK.type(tl,document.querySelector("#type2"),5.6,{cps:15});
// Registry strikethrough-replace integration, with Twyne typography and copy.
[[1,2.05],[2,7.2]].forEach(([i,at])=>{
tl.fromTo("#old"+i+" i",{"--hf-strike-progress":0},{"--hf-strike-progress":1,duration:.28,ease:"power2.out"},at);
tl.fromTo("#new"+i,{"--hf-replace-opacity":0,y:14},{"--hf-replace-opacity":1,y:0,duration:.4,ease:"power2.out"},at+.24);
tl.fromTo("#note"+i,{opacity:0},{opacity:1,duration:.4},at+.8);
});
tl.fromTo("#mark",{opacity:0,scale:.85},{opacity:1,scale:1,duration:.6,ease:"back.out(1.2)"},10.85);
tl.fromTo("#wm",{opacity:0,y:28},{opacity:1,y:0,duration:.65,ease:"expo.out"},11.1);
tl.fromTo("#tag",{opacity:0},{opacity:1,duration:.5},11.6);
