.mark {width:165px;height:165px;margin-bottom:30px}
.wm {display:flex;font-family:var(--display);font-weight:700;font-size:160px;line-height:1.1;letter-spacing:.08em;padding-left:.08em;margin:0}
.letter {display:inline-block}
.tag {font-family:var(--serif);font-style:italic;font-size:48px;line-height:1.35;color:var(--ink-light);margin-top:32px}
